async fn add_to_cart(jar: PrivateCookieJar, Json(sku): Json<Sku>) -> (PrivateCookieJar, StatusCode) {
    let cart = jar.get("cart")
        .and_then(|c| serde_json::from_str::<Cart>(c.value()).ok())
        .unwrap_or_default()
        .push(sku);
    let jar = jar.add(Cookie::new("cart", serde_json::to_string(&cart).unwrap()));
    (jar, StatusCode::NO_CONTENT)          // the updated jar must be returned or no Set-Cookie is sent
}

